// src/components/Equipment.js
import React from 'react';
import styled from 'styled-components';

const EquipmentGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
`;

const EquipmentItem = styled.div`
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 10px;
  background-color: ${({ isSelected }) => (isSelected ? '#d1e7dd' : '#fff')};
  text-align: center;
  cursor: pointer;
  transition: box-shadow 0.3s ease;

  &:hover {
    box-shadow: 0 8px 16px rgba(0, 0, 0, 0.1);
  }
`;

const EquipmentImage = styled.img`
  width: 100%;
  height: 200px;
  object-fit: cover;
  border-radius: 8px;
`;

const Equipment = ({ equipment, handleSelect, selectedItems = [] }) => {
  const isSelected = (item) =>
    selectedItems.some((selected) => selected.id === item.id);

  return (
    <EquipmentGrid>
      {equipment.map((item) => (
        <EquipmentItem
          key={item.id}
          isSelected={isSelected(item)}
          onClick={() => handleSelect(item)}
        >
          <EquipmentImage src={item.Image_URL} alt={item.Name} />
          <h3>{item.Name}</h3>
          <p>Brand: {item.Brand}</p>
          <p>Price: ${item.Price}</p>
        </EquipmentItem>
      ))}
    </EquipmentGrid>
  );
};

export default Equipment;
